content.content:
  1	// Local API for the dashboard's live mode (TDD "Integrations and interfaces" -> Local API).
  2	//
  3	//   GET /api/bundles      index entries merged from every bundle directory (deduped by runId)
  4	//   GET /api/bundles/:id  one bundle, re-verified with verifyBundle on every read
  5	//   GET /api/bundles/:id/timeline  the run's TimelineFile (runs/<id>/timeline.jsonl, else the
  6	//                         published <id>.timeline.json next to the bundle); 404 when absent
  7	//   GET /api/stream       SSE of bus events (decision, probe.committed, probe.verdict,
  8	//                         belief.changed, run.finished, timeline) with Last-Event-ID replay
  9	//
 10	//   GET /api/health       per-integration status (src/api/health.ts; network checks cached ~60 s)
 11	//   GET /api/runs         finished real runs + runs this server started still running (src/api/runs.ts)
 12	//   GET /api/runs/:id     the verified bundle, or 202 {state:"running"}
 13	//   GET /api/runs/:id/events  SSE of the run's TimelineEvents (file replay, then live), `event: end`
 14	//   GET /api/certificates[/:id]  certificates from the real runs this server sees (src/api/certificates.ts)
 15	//
 16	//   POST /api/runs        start a real queue run / notarize in this process (src/api/runs.ts)
 17	//   POST /api/ask         Ask Notary (src/api/ask.ts): cited answers from the loaded records
 18	//                         (NOTARY_ASK_RPM per session, 429 + Retry-After; spans in runs/_ask/spans.jsonl)
 19	//   GET|POST /api/approvals, POST /api/approvals/:id/approve|reject  approval desk (src/api/approvals.ts)
 20	//   POST|GET /api/chat, GET|DELETE /api/chat/:id, POST /api/chat/:id/messages (SSE)  Notary Chat
 21	//                         (src/api/chat.ts; read-only tool agent, NOTARY_ASK_RPM per session, spans in
 22	//                         runs/_chat/spans.jsonl, conversations in runs/chat.sqlite)
 23	//
 24	// POST /api/runs, ask, chat and approvals need the per-session token (Authorization: Bearer) AND a loopback
 25	// socket, Host and Origin (src/api/session.ts). Everything else is read-only and unauthenticated as
 26	// before. CORS is limited to loopback dashboard dev origins. No handler returns canned data: every
 27	// response is read from run files, the environment, or a real integration check.
 28	// /api/runs, /api/certificates and /api/approvals never include sample/fixture bundles.
 29	// Only each bundle directory's own index.json is read; subdirectories of public/bundles are NOT
 30	// scanned, so the fixture-demo bundles in public/bundles/fixture/ (own index) are never merged
 31	// into the list. Under runs/, every immediate subdirectory is a bundle dir (runs/<runId>/).
 32	import { spawn } from "node:child_process";
 33	import { existsSync, readdirSync, statSync } from "node:fs";
 34	import { readFile } from "node:fs/promises";
 35	import { join, relative, resolve, isAbsolute } from "node:path";
 36	import { fileURLToPath } from "node:url";
 37	import { Hono } from "hono";
 38	import type { Context, MiddlewareHandler } from "hono";
 39	import { cors } from "hono/cors";
 40	import { streamSSE } from "hono/streaming";
 41	import { verifyBundle } from "../bundle/hash.js";
 42	import { BundleIndexSchema } from "../schema/bundle.js";
 43	import type { BundleIndexEntry } from "../schema/index.js";
 44	import { bus as defaultBus, DEFAULT_EVENT_JOURNAL, tailEventJournal } from "./bus.js";
 45	import type { EventBus, NotaryEvent } from "./bus.js";
 46	import { servedTimeline } from "../timeline/serve.js";
 47	import { listApprovals, mountApprovals } from "./approvals.js";
 48	import { loadVerifiedBundles } from "./bundle-source.js";
 49	import { mountCertificates, realCertificates } from "./certificates.js";
 50	import { CHAT_SPANS_DIR, mountChat } from "./chat.js";
 51	import type { ChatOptions } from "./chat.js";
 52	import type { GuardCoverageSummary } from "../chat/tools.js";
 53	import { createHealth } from "./health.js";
 54	import type { HealthOptions } from "./health.js";
 55	import { mountRuns } from "./runs.js";
 56	import type { RunTracker, RunsOptions } from "./runs.js";
 57	import type { ApprovalsOptions } from "./approvals.js";
 58	import { ASK_SPANS_DIR, mountAsk } from "./ask.js";
 59	import type { AskOptions } from "./ask.js";
 60	import { createSession } from "./session.js";
 61	import type { ApiSession, CreatedSession } from "./session.js";
 62	
 63	export const DEFAULT_WEB_BUNDLES_DIR = fileURLToPath(new URL("../../../web/public/bundles/", import.meta.url));
 64	export const DEFAULT_RUNS_DIR = fileURLToPath(new URL("../../runs/", import.meta.url));
 65	export const DEFAULT_KEEP_ALIVE_MS = 15_000;
 66	export const HASH_MISMATCH_HEADER = "X-Notary-Hash-Mismatch";
 67	
 68	/** Same rule writeBundle uses for file names: no separators, no leading dot. */
 69	const SAFE_RUN_ID = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
 70	/** Dashboard dev servers on loopback only (Vite, preview, any port). */
 71	const LOOPBACK_ORIGIN = /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])(:\d{1,5})?$/;
 72	
 73	export interface ApiOptions {
 74	  /** Directories holding an index.json plus <runId>.json files. Earlier directories win on duplicate runIds. */
 75	  bundleDirs?: string[];
 76	  /** Each immediate subdirectory (runs/<runId>/) is also treated as a bundle directory. null disables. */
 77	  runsDir?: string | null;
 78	  bus?: EventBus;
 79	  keepAliveMs?: number;
 80	  /**
 81	   * Per-session token check for POST /api/ask and GET/POST /api/approvals (src/api/session.ts).
 82	   * Absent: a fresh random session nobody knows the token of, so those endpoints answer 401.
 83	   */
 84	  session?: ApiSession;
 85	  /** POST /api/ask options (test seams: model double, env). */
 86	  ask?: Omit<AskOptions, "bundleDirs">;
 87	  /** /api/chat options (test seams: model double, env, fetch, store, tools). */
 88	  chat?: Omit<ChatOptions, "session" | "runsDir" | "bundleDirs">;
 89	  /** GET/POST /api/approvals options (test seams: env, tools, store, manifest). */
 90	  approvals?: Omit<ApprovalsOptions, "runsDir" | "bus">;
 91	  /** GET /api/health options (test seams: env, probes, clock). */
 92	  health?: HealthOptions;
 93	  /** POST/GET /api/runs options (test seams: env, runners, precheck). */
 94	  runs?: Pick<RunsOptions, "env" | "now" | "runQueue" | "notarize" | "precheck">;
 95	  /** Receives this app's run tracker (tests). */
 96	  onRunTracker?: (tracker: RunTracker) => void;
 97	  /**
 98	   * Hosted, read-only deployment (src/api/hosted.ts): ask and chat use `guard` (a bearer token from
 99	   * AWS Secrets Manager) instead of localhost + session token; approvals and starting runs are not
100	   * mounted at all (404 / 405); CORS allows `allowedOrigins` instead of loopback dev origins.
101	   */
102	  hosted?: { guard: MiddlewareHandler; allowedOrigins: readonly string[] };
103	  /** Guard coverage for Notary Chat (default: src/guards/coverage.ts, tsc walk, cached GUARD_COVERAGE_TTL_MS). */
104	  guardCoverage?: () => Promise<GuardCoverageSummary>;
105	}
106	
107	/** How long a computed guard coverage report is reused by chat (the walk takes seconds). */
108	export const GUARD_COVERAGE_TTL_MS = 10 * 60_000;
109	
110	/** A coverage walk that runs longer than this is killed (the tool then says it could not check). */
111	export const GUARD_COVERAGE_TIMEOUT_MS = 240_000;
112	
113	/** Run src/agents/coverage-child.ts in a child process (same runtime flags, so tsx works) and parse its one JSON line. */
114	export function guardCoverageInChild(timeoutMs = GUARD_COVERAGE_TIMEOUT_MS): Promise<GuardCoverageSummary> {
115	  return new Promise((res, rej) => {
116	    const child = spawn(process.execPath, [...process.execArgv, fileURLToPath(new URL("../agents/coverage-child.ts", import.meta.url))], { stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
117	    let out = "";
118	    let err = "";
119	    const timer = setTimeout(() => {
120	      child.kill();
121	      rej(new Error(`the coverage walk took longer than ${Math.round(timeoutMs / 1000)} s`));
122	    }, timeoutMs);
123	    child.stdout.on("data", (d: Buffer) => (out += d.toString("utf8")));
124	    child.stderr.on("data", (d: Buffer) => (err = (err + d.toString("utf8")).slice(-2000)));
125	    child.on("error", (e) => (clearTimeout(timer), rej(e)));
126	    child.on("close", (code) => {
127	      clearTimeout(timer);
128	      const line = out.trim().split(/\r?\n/).at(-1) ?? "";
129	      try {
130	        if (code !== 0) throw new Error(`exit ${code}: ${err.trim().split(/\r?\n/).at(-1) ?? ""}`);
131	        res(JSON.parse(line) as GuardCoverageSummary);
132	      } catch (e) {
133	        rej(e instanceof Error ? e : new Error(String(e)));
134	      }
135	    });
136	  });
137	}
138	
139	/** Default guard coverage source: the same tsc walk as `notary guards coverage`, in a child process, computed lazily and cached. */
140	export function cachedGuardCoverage(ttlMs = GUARD_COVERAGE_TTL_MS, now: () => number = Date.now): () => Promise<GuardCoverageSummary> {
141	  let cached: { at: number; value: Promise<GuardCoverageSummary> } | null = null;
142	  return () => {
143	    if (cached && now() - cached.at < ttlMs) return cached.value;
144	    const value = guardCoverageInChild();
145	    cached = { at: now(), value };
146	    value.catch(() => (cached = null));
147	    return value;
148	  };
149	}
150	
151	interface IndexedEntry {
152	  entry: BundleIndexEntry;
153	  dir: string;
154	}
155	
156	function bundleDirectories(opts: ApiOptions): string[] {
157	  const dirs = [...(opts.bundleDirs ?? [DEFAULT_WEB_BUNDLES_DIR])];
158	  const runsDir = opts.runsDir === undefined ? DEFAULT_RUNS_DIR : opts.runsDir;
159	  if (runsDir !== null && existsSync(runsDir)) {
160	    for (const name of readdirSync(runsDir).sort()) {
161	      const sub = join(runsDir, name);
162	      try {
163	        if (statSync(sub).isDirectory()) dirs.push(sub);
164	      } catch {
165	        // vanished between readdir and stat
166	      }
167	    }
168	  }
169	  return dirs;
170	}
171	
172	/** Merge every directory's index.json; invalid or missing indexes are skipped. First directory wins per runId. */
173	async function loadIndex(opts: ApiOptions): Promise<Map<string, IndexedEntry>> {
174	  const byId = new Map<string, IndexedEntry>();
175	  for (const dir of bundleDirectories(opts)) {
176	    const indexPath = join(dir, "index.json");
177	    if (!existsSync(indexPath)) continue;
178	    let raw: unknown;
179	    try {
180	      raw = JSON.parse(await readFile(indexPath, "utf8"));
181	    } catch {
182	      continue;
183	    }
184	    const parsed = BundleIndexSchema.safeParse(raw);
185	    if (!parsed.success) continue;
186	    for (const entry of parsed.data) {
187	      if (!SAFE_RUN_ID.test(entry.runId) || byId.has(entry.runId)) continue;
188	      byId.set(entry.runId, { entry, dir });
189	    }
190	  }
191	  return byId;
192	}
193	
194	function sortEntries(entries: BundleIndexEntry[]): BundleIndexEntry[] {
195	  return entries.sort(
196	    (x, y) => Date.parse(x.startedAt) - Date.parse(y.startedAt) || (x.runId < y.runId ? -1 : x.runId > y.runId ? 1 : 0),
197	  );
198	}
199	
200	function isInside(dir: string, file: string): boolean {
201	  const rel = relative(resolve(dir), resolve(file));
202	  return rel !== "" && !rel.startsWith("..") && !isAbsolute(rel);
203	}
204	
205	function parseLastEventId(value: string | undefined): number | undefined {
206	  if (value === undefined || !/^\d{1,15}$/.test(value.trim())) return undefined;
207	  return Number(value.trim());
208	}
209	
210	export function createApp(opts: ApiOptions = {}): Hono {
211	  const bus = opts.bus ?? defaultBus;
212	  const keepAliveMs = opts.keepAliveMs ?? DEFAULT_KEEP_ALIVE_MS;
213	  const app = new Hono();
214	
215	  app.use(
216	    "/api/*",
217	    cors({
218	      origin: (origin) => (opts.hosted ? (opts.hosted.allowedOrigins.includes(origin) ? origin : null) : LOOPBACK_ORIGIN.test(origin) ? origin : null),
219	      // POST + Authorization + Content-Type for the token-protected ask/approvals endpoints; loopback origins only.
220	      allowMethods: ["GET", "HEAD", "POST", "DELETE", "OPTIONS"],
221	      allowHeaders: ["Last-Event-ID", "Cache-Control", "Authorization", "Content-Type"],
222	      // Retry-After: the ask endpoint's 429 (rate limit) tells the dashboard when to try again.
223	      exposeHeaders: [HASH_MISMATCH_HEADER, "Retry-After"],
224	    }),
225	  );
226	
227	  app.get("/api/bundles", async (c) => {
228	    const index = await loadIndex(opts);
229	    return c.json(sortEntries([...index.values()].map((v) => v.entry)));
230	  });
231	
232	  /** One indexed bundle, re-verified on every read (GET /api/bundles/:id and GET /api/runs/:id). */
233	  const bundleResponse = async (c: Context, found: IndexedEntry, id: string): Promise<Response> => {
234	    const file = join(found.dir, `${id}.json`);
235	    if (!isInside(found.dir, file)) return c.json({ error: "invalid bundle id" }, 400);
236	    if (!existsSync(file)) return c.json({ error: `bundle ${id} is indexed but its file is missing` }, 404);
237	
238	    let raw: unknown;
239	    try {
240	      raw = JSON.parse(await readFile(file, "utf8"));
241	    } catch (err) {
242	      return c.json({ error: `bundle ${id} is not valid JSON: ${(err as Error).message}` }, 500);
243	    }
244	    const checked = verifyBundle(raw);
245	    if (checked.ok) return c.json(checked.bundle);
246	    if (checked.reason === "hash") {
247	      // TDD: a tampered bundle must fail visibly. Serve it so the dashboard can show it next to the error.
248	      c.header(HASH_MISMATCH_HEADER, "1");
249	      return c.json({ ...checked.bundle, error: checked.error });
250	    }
251	    return c.json({ error: checked.error }, 500);
252	  };
253	
254	  app.get("/api/bundles/:id", async (c) => {
255	    const id = c.req.param("id");
256	    if (!SAFE_RUN_ID.test(id)) return c.json({ error: "invalid bundle id" }, 400);
257	    const found = (await loadIndex(opts)).get(id);
258	    if (!found) return c.json({ error: `unknown bundle ${id}` }, 404);
259	    return await bundleResponse(c, found, id);
260	  });
261	
262	  app.get("/api/bundles/:id/timeline", async (c) => {
263	    const id = c.req.param("id");
264	    if (!SAFE_RUN_ID.test(id)) return c.json({ error: "invalid bundle id" }, 400);
265	    const found = (await loadIndex(opts)).get(id);
266	    if (!found) return c.json({ error: `unknown bundle ${id}` }, 404);
267	    const served = servedTimeline({ id, entry: found.entry, dir: found.dir, runsDir: opts.runsDir === undefined ? DEFAULT_RUNS_DIR : opts.runsDir });
268	    return served.ok ? c.json(served.file) : c.json({ error: served.error }, served.status);
269	  });
270	
271	  app.get("/api/stream", (c) => {
272	    // EventSource sends Last-Event-ID on reconnect; a first connection can pass ?lastEventId=0 to
273	    // replay everything still buffered. Without either, only new events are sent.
274	    const afterId = parseLastEventId(c.req.header("Last-Event-ID") ?? c.req.query("lastEventId"));
275	    return streamSSE(c, async (stream) => {
276	      const pending: NotaryEvent[] = [];
277	      let wake: (() => void) | null = null;
278	      const unsubscribe = bus.subscribe((event) => {
279	        pending.push(event);
280	        wake?.();
281	      });
282	      const stop = (): void => {
283	        unsubscribe();
284	        wake?.();
285	      };
286	      stream.onAbort(stop);
287	      c.req.raw.signal.addEventListener("abort", () => stream.abort(), { once: true });
288	
289	      try {
290	        // Subscribe first, then replay, then dedupe by id: no gap and no duplicate at the seam.
291	        let lastSent = afterId ?? bus.lastId;
292	        const replay = afterId === undefined ? [] : bus.since(afterId);
293	        await stream.write(`retry: 3000\n: connected\n\n`);
294	        if (afterId !== undefined && replay.length > 0 && replay[0]!.id > afterId + 1) {
295	          await stream.write(`: replay truncated; events ${afterId + 1}-${replay[0]!.id - 1} left the buffer\n\n`);
296	        }
297	        const send = async (event: NotaryEvent): Promise<void> => {
298	          if (event.id <= lastSent) return;
299	          await stream.writeSSE({ event: event.type, id: String(event.id), data: JSON.stringify({ at: event.at, payload: event.payload }) });
300	          lastSent = event.id;
301	        };
302	        for (const event of replay) await send(event);
303	
304	        while (!stream.aborted && !stream.closed) {
305	          while (pending.length > 0 && !stream.aborted) await send(pending.shift()!);
306	          if (stream.aborted) break;
307	          let timer: NodeJS.Timeout | undefined;
308	          const timedOut = await new Promise<boolean>((res) => {
309	            wake = () => res(false);
310	            timer = setTimeout(() => res(true), keepAliveMs);
311	          });
312	          wake = null;
313	          clearTimeout(timer);
314	          if (timedOut && pending.length === 0 && !stream.aborted) await stream.write(": keep-alive\n\n");
315	        }
316	      } finally {
317	        unsubscribe();
318	      }
319	    });
320	  });
321	
322	  const session = opts.session ?? createSession();
323	  const runsDir = opts.runsDir === undefined ? DEFAULT_RUNS_DIR : opts.runsDir;
324	  const verifiedBundles = () => loadVerifiedBundles(bundleDirectories(opts));
325	
326	  const health = createHealth(opts.health ?? {});
327	  app.get("/api/health", async (c) => c.json(await health.check()));
328	
329	  mountCertificates(app, { verifiedBundles });
330	
331	  // Hosted: read-only. Starting runs and the approvals desk are refused before any other handler.
332	  if (opts.hosted) {
333	    app.post("/api/runs", (c) => c.json({ error: "the hosted Notary site is read-only: runs are started from the CLI or the agents task" }, 405));
334	    app.all("/api/approvals", (c) => c.json({ error: "approvals are not available on the hosted read-only site; use a local notary serve" }, 404));
335	    app.all("/api/approvals/*", (c) => c.json({ error: "approvals are not available on the hosted read-only site; use a local notary serve" }, 404));
336	  }
337	
338	  // Runs (POST is token + localhost); reads are open like the bundle endpoints.
339	  const { tracker } = mountRuns(app, {
340	    ...opts.runs,
341	    runsDir,
342	    bus,
343	    session,
344	    keepAliveMs,
345	    loadIndex: () => loadIndex(opts),
346	    verifiedBundles,
347	    bundleResponse,
348	  });
349	  opts.onRunTracker?.(tracker);
350	
351	  // The other non-read endpoints: token + localhost (src/api/session.ts). Ask is read-only by construction.
352	  mountAsk(app, {
353	    runsDir,
354	    // Ask spans get their own local sink (runs/_ask/spans.jsonl), scoped to each ask's async context,
355	    // so they never land in an approval's runs/<runId>/spans.jsonl (approvals swap the global sink).
356	    spansPath: runsDir === null ? null : join(runsDir, ASK_SPANS_DIR, "spans.jsonl"),
357	    ...opts.ask,
358	    ...(opts.hosted ? { guard: opts.hosted.guard } : {}),
359	    session,
360	    bundleDirs: () => bundleDirectories(opts),
361	  });
362	  // Notary Chat (token + localhost). Its certificate, approvals and health readers are injected here so
363	  // the chat module itself never imports approval/queue/certify code (test/chat-safety.test.ts).
364	  const approvalsRead = { ...opts.approvals, runsDir, bus };
365	  mountChat(app, {
366	    runsDir,
367	    spansPath: runsDir === null ? null : join(runsDir, CHAT_SPANS_DIR, "spans.jsonl"),
368	    certificates: () => realCertificates({ verifiedBundles }),
369	    // Hosted: the approvals desk is not exposed, not even read-only through chat.
370	    ...(opts.hosted ? {} : { approvals: () => listApprovals(approvalsRead) }),
371	    health: () => health.check(),
372	    guardCoverage: opts.guardCoverage ?? cachedGuardCoverage(),
373	    ...opts.chat,
374	    ...(opts.hosted ? { guard: opts.hosted.guard } : {}),
375	    session,
376	    bundleDirs: () => bundleDirectories(opts),
377	  });
378	  if (!opts.hosted) {
379	    mountApprovals(app, {
380	      ...opts.approvals,
381	      session,
382	      runsDir: opts.runsDir === undefined ? DEFAULT_RUNS_DIR : opts.runsDir,
383	      bus,
384	    });
385	  }
386	
387	  // Everything else is read-only: any other write is refused explicitly.
388	  app.on(["POST", "PUT", "PATCH", "DELETE"], "/api/*", (c) => c.json({ error: "the Notary API is read-only" }, 405));
389	
390	  return app;
391	}
392	
393	export interface StartedServer {
394	  url: string;
395	  close: () => Promise<void>;
396	  /** This server's session (its token is shown once at startup by `notary serve`, never stored). */
397	  session: CreatedSession;
398	}
399	
400	/** Bind the API with @hono/node-server. Loopback by default. */
401	export async function startServer(
402	  opts: Omit<ApiOptions, "session"> & { port?: number; host?: string; eventJournal?: string | null; session?: CreatedSession; prewarmGuardCoverage?: boolean } = {},
403	): Promise<StartedServer> {
