129	// Security layer for the local API's write-capable endpoints (POST /api/runs, POST /api/ask, GET/POST /api/approvals/**).
130	//
131	// - A per-session token: 32 crypto-random bytes (base64url), created when `notary serve` starts and
132	//   printed once to the terminal. It lives only in this process's memory: never written to a file,
133	//   the event journal, a span or a log. Compared in constant time (sha256 digests + timingSafeEqual,
134	//   so the token length leaks nothing either). Sent as `Authorization: Bearer <token>`.
135	// - Localhost only: the socket's remote address must be loopback, the Host header must name
136	//   localhost / 127.0.0.1 / [::1] (any port; DNS-rebinding defence), and an Origin, when sent, must be
137	//   a loopback origin. A request with no socket (no remote address) is refused.
138	//
139	// Order: localhost checks first (403), then the token (401). Error bodies never echo request headers.
140	import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
141	import type { Context, MiddlewareHandler } from "hono";
142	
143	export const SESSION_TOKEN_BYTES = 32;
144	
145	/** Dashboard dev servers on loopback only (Vite, preview, any port). Same rule as the CORS policy. */
146	export const LOOPBACK_ORIGIN = /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])(:\d{1,5})?$/;
147	const LOOPBACK_HOST = /^(localhost|127\.0\.0\.1|\[::1\])(:\d{1,5})?$/i;
148	
149	export interface ApiSession {
150	  /** Constant-time check of a presented token. */
151	  verify(presented: string | undefined | null): boolean;
152	}
153	
154	export interface CreatedSession extends ApiSession {
155	  /** The token, for the one startup line. Do not log, persist or trace it anywhere else. */
156	  readonly token: string;
157	}
158	
159	function digest(s: string): Buffer {
160	  return createHash("sha256").update(s, "utf8").digest();
161	}
162	
163	export function createSession(token: string = randomBytes(SESSION_TOKEN_BYTES).toString("base64url")): CreatedSession {
164	  if (token.length < 32) throw new RangeError("session token too short");
165	  const expected = digest(token);
166	  const session = {
167	    verify(presented: string | undefined | null): boolean {
168	      if (typeof presented !== "string" || presented.length === 0) return false;
169	      return timingSafeEqual(digest(presented), expected);
170	    },
171	  } as CreatedSession;
172	  // Non-enumerable: JSON.stringify / console.log of the session object never shows the token.
173	  Object.defineProperty(session, "token", { value: token, enumerable: false });
174	  return session;
175	}
176	
177	/** The startup hint printed once by `notary serve`. The only place the token is ever shown. */
178	export function sessionBanner(baseUrl: string, token: string): string[] {
179	  return [
180	    `  session token (this run only; never stored): ${token}`,
181	    `  POST ${baseUrl}/api/runs  POST ${baseUrl}/api/ask  GET|POST ${baseUrl}/api/approvals[/:id/approve|reject]  /api/chat[/:id[/messages]]  need: Authorization: Bearer <token>`,
182	  ];
183	}
184	
185	export function isLoopbackAddress(address: string | undefined | null): boolean {
186	  if (!address) return false;
187	  const a = address.trim().toLowerCase();
188	  if (a === "::1" || a === "0:0:0:0:0:0:0:1") return true;
189	  const v4 = a.startsWith("::ffff:") ? a.slice(7) : a;
190	  return /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(v4);
191	}
192	
193	export function isLoopbackHost(host: string | undefined | null): boolean {
194	  return typeof host === "string" && LOOPBACK_HOST.test(host.trim());
195	}
196	
197	export function isLoopbackOrigin(origin: string): boolean {
198	  return LOOPBACK_ORIGIN.test(origin);
199	}
200	
201	/** Remote address of the socket (@hono/node-server bindings), undefined when there is no socket. */
202	export function remoteAddressOf(c: Context): string | undefined {
203	  const env = c.env as { server?: { incoming?: unknown }; incoming?: unknown } | undefined;
204	  const incoming = (env?.server?.incoming ?? env?.incoming) as { socket?: { remoteAddress?: string } } | undefined;
205	  return incoming?.socket?.remoteAddress;
206	}
207	
208	export type LocalCheck = { ok: true } | { ok: false; status: 401 | 403; error: string };
209	
210	/** Pure check of one request (exported for tests). */
211	export function checkLocalRequest(
212	  session: ApiSession,
213	  req: { remoteAddress: string | undefined; host: string | undefined; origin: string | undefined; authorization: string | undefined },
214	): LocalCheck {
215	  if (!isLoopbackAddress(req.remoteAddress)) return { ok: false, status: 403, error: "forbidden: local API accepts loopback connections only" };
216	  if (!isLoopbackHost(req.host)) return { ok: false, status: 403, error: "forbidden: Host must be localhost, 127.0.0.1 or [::1]" };
217	  if (req.origin !== undefined && !isLoopbackOrigin(req.origin)) return { ok: false, status: 403, error: "forbidden: cross-origin request from a non-loopback origin" };
218	  const m = /^Bearer\s+(\S+)\s*$/i.exec(req.authorization ?? "");
219	  if (!m || !session.verify(m[1])) return { ok: false, status: 401, error: "unauthorized: send Authorization: Bearer <session token printed by notary serve>" };
220	  return { ok: true };
221	}
222	
223	/** Hono middleware: token + localhost. */
224	export function requireLocalSession(session: ApiSession): MiddlewareHandler {
225	  return async (c, next) => {
226	    const verdict = checkLocalRequest(session, {
227	      remoteAddress: remoteAddressOf(c),
228	      host: c.req.header("Host"),
229	      origin: c.req.header("Origin"),
230	      authorization: c.req.header("Authorization"),
231	    });
232	    if (!verdict.ok) {
233	      if (verdict.status === 401) c.header("WWW-Authenticate", 'Bearer realm="notary"');
234	      return c.json({ error: verdict.error }, verdict.status);
235	    }
236	    await next();
237	  };
238	}

