209	export async function runTurn(input: TurnInput, deps: AgentDeps): Promise<TurnResult> {
210	  let agentSet: (k: string, v: string | number | boolean) => void = () => {};
211	  const result = await withSpan(
212	    "notary.chat.agent",
213	    { [AGENT_SPAN_ATTR]: AGENTS.chat.name, [AGENT_ID_SPAN_ATTR]: "chat", "notary.chat.history_messages": input.history.length },
214	    async () => {
215	      const r = await loop(input, deps);
216	      agentSet("notary.chat.status", r.status);
217	      agentSet("notary.chat.steps", r.steps);
218	      agentSet("notary.chat.model_calls", r.modelCalls);
219	      agentSet("notary.chat.citations", r.citations.total);
220	      agentSet("notary.chat.citations_invalid", r.citations.invalid);
221	      return r;
222	    },
223	    { kind: "AGENT", onSpan: (_ids, set) => (agentSet = set) },
224	  );
225	  return result;
226	}
227	
228	async function loop(input: TurnInput, deps: AgentDeps): Promise<TurnResult> {
229	  const clock = deps.clock ?? (() => performance.now());
230	  const clean = deps.clean ?? ((s: string) => s);
231	  const maxSteps = deps.maxSteps ?? CHAT_MAX_STEPS;
232	  const t0 = clock();
233	  const { signal } = deps;
234	  const steps: (TurnStep & { tool: string; key: string })[] = [];
235	  const usage = { input: 0, output: 0, usd: 0, unknown: false, calls: 0 };
236	  const money = detectMoneyRequest(input.content);
237	  const system = systemPrompt(maxSteps);
238	  const specs = chatToolSpecs();
239	  let visible = "";
240	  let citations = { total: 0, invalid: 0 };
241	
242	  const emit = (e: ChatEvent): void => deps.emit(e);
243	  const emitText = (t: string): void => {
244	    for (const piece of chunkText(t)) emit({ type: "text_delta", text: piece });
245	  };
246	  const result = (status: TurnResult["status"], error?: string): TurnResult => ({
247	    status,
248	    content: visible,
249	    steps: steps.length,
250	    tokens: { input: usage.input, output: usage.output },
251	    costUsd: usage.unknown ? null : Math.round(usage.usd * 1e9) / 1e9,
252	    modelCalls: usage.calls,
253	    citations,
254	    moneyRequest: money.moneyMoving,
255	    ...(error ? { error } : {}),
256	  });
257	
258	  const ctx: ToolContext = { ...deps.tools, signal, usdSpent: () => usage.usd };
259	
260	  const callModel = async (messages: AgentMessage[], toolChoice: ToolChoice): Promise<ToolCompleteResult> => {
261	    if (signal.aborted) throw new Aborted();
262	    let r: ToolCompleteResult;
263	    try {
264	      r = await deps.llm.completeTools({ role: "chat", agent: "chat", system, messages, tools: specs, toolChoice, maxTokens: CALL_MAX_TOKENS, signal });
265	    } catch (err) {
266	      if (signal.aborted) throw new Aborted();
267	      const msg = clean(err instanceof Error ? err.message : String(err));
268	      if (msg.startsWith("BLOCKED:")) throw new TurnError(msg, "Fix the variable named above in .env, restart `pnpm notary serve`, then run `pnpm notary doctor --llm`");
269	      if (isUsdCapExceeded(err)) throw new TurnError(msg, "Raise NOTARY_MAX_USD in .env (or unset it), then restart `pnpm notary serve`");
270	      if (err instanceof LlmRateLimitedError) throw new TurnError(msg, "Wait a minute and ask again, or raise NOTARY_LLM_RPM / NOTARY_LLM_CONCURRENCY in .env; `pnpm notary doctor --llm` shows the limits");
271	      throw new TurnError(`${AGENTS.chat.name}'s model call failed: ${msg}`, DOCTOR_FIX);
272	    }
273	    usage.calls += 1;
274	    usage.input += r.inputTokens;
275	    usage.output += r.outputTokens;
276	    usage.usd += r.usd;
277	    if (r.priceSource === "unknown") usage.unknown = true;
278	    if (signal.aborted) throw new Aborted();
279	    return r;
280	  };
281	
282	  /** Run one validated tool call as a step; returns the text the model gets back as the tool result. */
283	  const runStep = async (def: ChatToolDef, args: Record<string, unknown>): Promise<string> => {
284	    const id = `s${steps.length + 1}`;
285	    const inputSummary = clean(def.input(args));
286	    emit({ type: "step_started", id, tool: def.name, title: clean(def.title(args)), input: inputSummary });
287	    const started = clock();
288	    let run: ToolRun | "aborted" = "aborted";
289	    let set: (k: string, v: string | number | boolean) => void = () => {};
290	    // The span body returns a small summary only (the SDK records the return value); the result stays here.
291	    await withSpan(
292	      "notary.chat.tool",
293	      {
294	        [AGENT_SPAN_ATTR]: AGENTS.chat.name,
295	        [AGENT_ID_SPAN_ATTR]: "chat",
296	        "notary.tool": def.name,
297	        "notary.chat.tool": def.name,
298	        "notary.chat.step_id": id,
299	        "notary.chat.input_chars": inputSummary.length,
300	      },
301	      async () => {
302	        try {
303	          run = await def.run(args, ctx);
304	        } catch (err) {
305	          if (signal.aborted) run = "aborted";
306	          else {
307	            const msg = clean(err instanceof Error ? err.message : String(err));
308	            run = { status: "error", output: clip(`Failed: ${msg}`, 200), modelText: `ERROR: the tool failed (${clip(msg, 300)}). Nothing was learned from this step.`, citables: [] };
309	          }
310	        }
311	        if (signal.aborted) run = "aborted";
312	        const r = run as ToolRun | "aborted";
313	        set("notary.chat.status", r === "aborted" ? "aborted" : r.status);
314	        set("notary.chat.duration_ms", Math.max(0, Math.round(clock() - started)));
315	        if (r !== "aborted") {
316	          set("notary.chat.citables", r.citables.length);
317	          // Record ids only (never record content); the step id stands in for an API response.
318	          set("notary.recordIds", clip(r.citables.map((c) => (c.id === STEP_ID_PLACEHOLDER ? id : c.id)).join(","), 1000));
319	          if (r.credits !== undefined) set("notary.chat.credits", r.credits);
320	        }
321	        return { status: r === "aborted" ? "aborted" : r.status };
322	      },
323	      { kind: "TOOL", onSpan: (_ids, setter) => (set = setter) },
324	    );
325	    const durationMs = Math.max(0, Math.round(clock() - started));
326	    if (run === "aborted") {
327	      emit({ type: "step_finished", id, status: "aborted", durationMs, costUsd: null, output: "Stopped by the user" });
328	      steps.push({ id, status: "aborted", citables: [], tool: def.name, key: "" });
329	      throw new Aborted();
330	    }
331	    run = run as ToolRun;
332	    const citables = run.citables.map((c) => (c.id === STEP_ID_PLACEHOLDER ? { ...c, id } : c));
333	    const data = capData(run.data);
334	    emit({
335	      type: "step_finished",
336	      id,
337	      status: run.status,
338	      durationMs,
339	      costUsd: null,
340	      ...(run.credits !== undefined ? { credits: run.credits } : {}),
341	      output: clean(run.output),
342	      ...(data !== undefined ? { data: JSON.parse(clean(JSON.stringify(data))) } : {}),
343	      ...(run.fix ? { fix: clean(run.fix) } : {}),
344	    });
345	    steps.push({ id, status: run.status, citables, tool: def.name, key: `${def.name}:${JSON.stringify(args)}` });
346	    const citeLine = citables.length
347	      ? `\nCitable from ${id}: ${citables.map((c) => `${c.type} ${c.id}`).join(", ")}`
348	      : run.status === "ok"
349	        ? `\nCitable from ${id}: api_response ${id}`
350	        : "";
351	    return clean(`Result of step ${id} (${def.name} ${inputSummary || "{}"}) — status ${run.status}:\n${clip(run.modelText, TOOL_TEXT_CHARS)}${citeLine}`);
352	  };
353	
354	  const convo: AgentMessage[] = [...historyMessages(input.history), { role: "user", content: input.content }];
355	
356	  try {
357	    // Deterministic: an obvious money-moving request gets a real read of what is held, and the model is told it can't act.
358	    if (money.moneyMoving) {
359	      const resultText = await runStep(toolByName("list_approvals")!, {});
360	      convo.push({
361	        role: "user",
362	        content: `[Notary: this message asks to move money or change something ("${money.verb}"). Chat cannot do that — no tool can write. Notary ran ${steps[steps.length - 1]!.id} (list_approvals) to show what is actually held. Answer any other part of the question with your tools as usual.]\n${resultText}`,
363	      });
364	    }
365	
366	    // The agent loop: the model calls tools until it answers (or the step cap forces an answer).
367	    let answer: string | null = null;
368	    let invalidRounds = 0;
369	    let capped = false;
370	    while (answer === null) {
371	      const toolSteps = steps.length - (money.moneyMoving ? 1 : 0);
372	      if (!capped && toolSteps >= maxSteps) {
373	        capped = true;
374	        convo.push({ role: "user", content: chatStepCapNudge(maxSteps) });
375	      }
376	      const reply = await callModel(convo, capped ? "none" : "auto");
377	      if (!reply.toolCalls.length || capped) {
378	        answer = reply.text;
379	        break;
380	      }
381	      // The model's words next to its calls are its note (≤ 20 words).
382	      if (reply.text.trim()) emit({ type: "note", text: clean(shortNote(reply.text)), source: "model" });
383	      // Ids must be unique per call for the provider to pair results; fill any the provider left empty.
384	      const calls = reply.toolCalls.map((c, i) => ({ ...c, id: c.id || `call_${usage.calls}_${i}` }));
385	      convo.push({ role: "assistant", content: reply.text, toolCalls: calls });
386	      let validThisRound = 0;
387	      for (const call of calls) {
388	        let out: string;
389	        const checked = checkToolCall(call);
390	        if (!checked.ok) out = `Not run: ${checked.reason}. Fix the call or answer from what you have.`;
391	        else {
392	          validThisRound += 1;
393	          const key = `${checked.def.name}:${JSON.stringify(checked.args)}`;
394	          const dup = steps.find((s) => s.key === key);
395	          if (dup) out = `Not run again: you already ran ${checked.def.name} with these arguments in step ${dup.id}; its result is above.`;
396	          else if (steps.length - (money.moneyMoving ? 1 : 0) >= maxSteps) out = `Not run: the limit of ${maxSteps} tool calls for this question is reached.`;
397	          else out = await runStep(checked.def, checked.args);
398	        }
399	        // Every tool call gets exactly one tool result (providers require the pairing).
400	        convo.push({ role: "tool", toolCallId: call.id, name: call.name, content: out });
401	      }
402	      invalidRounds = validThisRound === 0 ? invalidRounds + 1 : 0;
403	      if (invalidRounds >= MAX_INVALID_ROUNDS) {
404	        throw new TurnError(`${AGENTS.chat.name}'s tool calls were invalid ${MAX_INVALID_ROUNDS} rounds in a row.`, `Ask again or rephrase the question; if it keeps happening, check ${CHAT_MODEL} with \`pnpm notary doctor --llm\``);
405	      }
406	    }
407	
408	    // The answer: strip and check the CITATIONS line, scrub secrets, emit in chunks.
409	    const splitter = new AnswerSplitter();
410	    const safe = deps.streamClean?.() ?? { push: (d: string) => clean(d), end: () => "" };
411	    let pendingWs = "";
412	    const show = (out: string): void => {
413	      if (!out) return;
414	      const text = pendingWs + out;
415	      const trimmed = text.replace(/\s+$/, "");
416	      pendingWs = text.slice(trimmed.length);
417	      if (trimmed) {
418	        visible += trimmed;
419	        emitText(trimmed);
420	      }
421	    };
422	    show(splitter.push(safe.push(answer)));
423	    show(splitter.push(safe.end()));
424	    show(splitter.end().text);
425	    const block = splitter.block;
426	    if (!visible.trim()) throw new TurnError(`${AGENTS.chat.name} returned an empty answer.`, DOCTOR_FIX);
427	    if (money.moneyMoving && !visible.includes(APPROVALS_PATH)) {
428	      const notice = `\n\n${MONEY_NOTICE}`;
429	      visible += notice;
430	      emitText(notice);
431	    }
432	    const checked = validateChatCitations(visible, block, steps);
433	    citations = { total: checked.items.length, invalid: checked.invalid };
434	    emit({ type: "citations", items: checked.items.map((c) => ({ ...c, label: clean(c.label) })) });
435	    const traceId = deps.traceId?.();
436	    const r = result("done");
437	    emit({
438	      type: "done",
439	      costUsd: r.costUsd,
440	      tokens: r.tokens,
441	      ...(traceId ? { traceId } : {}),
442	      steps: r.steps,
443	      durationMs: Math.max(0, Math.round(clock() - t0)),
444	      mode: "live",
445	    });
446	    return r;
447	  } catch (err) {
448	    if (err instanceof Aborted || signal.aborted) {
449	      emit({ type: "error", message: STOPPED_MESSAGE });
450	      return result("aborted", "stopped by the user");
451	    }
452	    if (err instanceof TurnError) {
453	      emit({ type: "error", message: clean(err.message), ...(err.fix ? { fix: clean(err.fix) } : {}) });
454	      return result("error", clean(err.message));
455	    }
456	    const msg = clean(err instanceof Error ? err.message : String(err));
457	    emit({ type: "error", message: `Chat failed: ${msg}`, fix: "See the `notary serve` terminal" });
458	    return result("error", msg);
459	  }
460	}

